function initials(name){ return name.split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase()||'TX'; }
function empty(message){ return `<div class="empty">${esc(message)}</div>`; }
function toast(message){ const el=$('#toast'); el.textContent=message; el.classList.add('show'); clearTimeout(el.timer); el.timer=setTimeout(()=>el.classList.remove('show'),2500); }
function dialogHasUnsavedWork(dialog){if(dialog?.id==='itemDialog')return itemFormBaseline&&serializeItemDraft()!==itemFormBaseline;if(dialog?.id==='receiveDialog')return receiveFormBaseline&&serializeReceiveDraft()!==receiveFormBaseline;return dialog?.dataset.dirty==='true';}
