function closeDialogDirect(dialog,result='cancel'){if(!dialog?.open)return;suppressDialogCancelGuard=true;dialog.close(result);dialog.inert=false;suppressDialogCancelGuard=false;}
function openDialog(dialog){if(!dialog||dialog.open)return;history.pushState({...navigationState(),hp67Modal:dialog.id},'');dialog.showModal();}
function requestDialogClose(dialog,after=null,{skipDirty=false}={}){
  if(!dialog?.open){if(after)requestAnimationFrame(after);return false;}
  if(pendingModalClose?.id===dialog.id)return false;
  if(!skipDirty&&dialogHasUnsavedWork(dialog)&&!confirm(dialogDiscardMessage(dialog)))return false;
  if(history.state?.hp67Modal===dialog.id){dialog.inert=true;pendingModalClose={id:dialog.id,after,approved:true};history.back();}
  else{closeDialogDirect(dialog);if(after)requestAnimationFrame(after);}
  return true;
}
function closeDialogSafely(dialog){return requestDialogClose(dialog);}
