function setMediaPending(kind,generation,delta){
  if(kind==='item'){
    if(generation!==itemEditGeneration)return;
    itemMediaPending=Math.max(0,itemMediaPending+delta);const button=$('#itemForm')?.querySelector('[type="submit"]');
    if(button){if(!button.dataset.readyLabel)button.dataset.readyLabel=button.textContent;button.disabled=itemMediaPending>0;button.textContent=itemMediaPending?'Foto wird verarbeitet …':button.dataset.readyLabel;}
    for(const id of ['#itemPhoto','#removeItemPhoto','#trainItemVisual','#clearItemVisual']){const control=$(id);if(control)control.disabled=itemMediaPending>0;}
  }else{
    if(generation!==locationEditGeneration)return;
    locationMediaPending=Math.max(0,locationMediaPending+delta);const button=$('#locationForm')?.querySelector('[type="submit"]');
    if(button){if(!button.dataset.readyLabel)button.dataset.readyLabel=button.textContent;button.disabled=locationMediaPending>0;button.textContent=locationMediaPending?'Fotos werden verarbeitet …':button.dataset.readyLabel;}
    for(const id of ['#trainLocationVisual','#clearLocationVisual']){const control=$(id);if(control)control.disabled=locationMediaPending>0;}
  }
}
