  let recognitionError='';voiceRecognition.onerror=e=>{if(run!==voiceRun||!$('#voiceDialog').open)return;recognitionError=e.error==='not-allowed'?'Mikrofonzugriff wurde nicht erlaubt – Text bitte unten eintippen':'Spracherkennung unterbrochen';setVoiceListening(false,recognitionError);if(e.error==='not-allowed')$('#voiceTranscript').focus();};
