function createGroupCode(ignoreId=''){
  const used=new Set([...state.items.map(item=>item.barcode),...(state.locations||[]).map(location=>location.code),...(state.barcodeGroups||[]).filter(group=>group.id!==ignoreId).map(group=>group.code)].map(code=>String(code||'').toLowerCase()).filter(Boolean));
  let code;do{code=`HP67-GRP-${String(Math.floor(Math.random()*1e8)).padStart(8,'0')}`;}while(used.has(code.toLowerCase()));return code;
}
