  $('#barcodeGroupList').innerHTML=state.barcodeGroups.length?state.barcodeGroups.map(group=>`<div class="category-row"><div><b>${esc(group.name)}</b><small>${esc(group.code)} · ${group.itemIds.length} Artikel</small></div><button type="button" data-group-edit="${esc(group.id)}">Bearbeiten</button><button type="button" data-group-delete="${esc(group.id)}">Löschen</button></div>`).join(''):empty('Noch keine Gruppenbarcodes angelegt.');
