function validateImportRows(incoming){
  const seenSku=new Set(),seenBarcode=new Set(),descriptorGroups=new Map();
  const integerFields=[['stock','Bestand'],['minStock','Mindestbestand']],priceFields=[['cost','EK'],['salePrice','VK Standard'],['onlinePrice','VK Online'],['marketPrice','VK Markt'],['wholesalePrice','VK B2B'],['specialPrice','Sonderpreis']];
  for(let index=0;index<incoming.length;index++){const row=incoming[index],sku=safeText(row.sku).toLowerCase(),barcode=safeText(row.barcode).toLowerCase(),descriptor=[normalizedText(row.name),normalizedText(row.color),normalizedText(row.size)].join('|');if(!safeText(row.name))throw Error(`Zeile ${index+2}: Artikelname fehlt.`);for(const[field,label]of integerFields)if(!Number.isInteger(row[field])||row[field]<0)throw Error(`Zeile ${index+2}: ${label} muss eine ganze Zahl ab 0 sein.`);for(const[field,label]of priceFields)if(!Number.isFinite(row[field])||row[field]<0)throw Error(`Zeile ${index+2}: ${label} muss eine Zahl ab 0 sein.`);if((sku&&seenSku.has(sku))||(barcode&&seenBarcode.has(barcode)))throw Error(`Doppelte Kennung in der Importdatei: ${row.name}${row.color?` · ${row.color}`:''}${row.size?` · ${row.size}`:''}`);if(sku)seenSku.add(sku);if(barcode)seenBarcode.add(barcode);const group=descriptorGroups.get(descriptor)||[];group.push({row,index,identified:!!(sku||barcode)});descriptorGroups.set(descriptor,group);}
  for(const group of descriptorGroups.values())if(group.length>1&&group.some(entry=>!entry.identified))throw Error(`Mehrdeutige Varianten in Zeile ${group.map(entry=>entry.index+2).join(', ')}. Bitte für jede gleich bezeichnete Variante eine eindeutige SKU oder einen Barcode eintragen.`);
}
function showImportPreview(incoming,fileName){if(!incoming.length)throw Error('Keine Artikel erkannt');validateImportRows(incoming);pendingImportRows=incoming;const matches=incoming.filter(row=>findImportMatch(row)).length;$('#importSummary').textContent=`${incoming.length} Varianten aus „${fileName}“ erkannt: ${matches} vorhandene Treffer, ${incoming.length-matches} neue Varianten. Zusammenführen nutzt zuerst SKU/Barcode, sonst Name + Marke + Farbe + Größe.`;$('#importPreviewRows').innerHTML=incoming.slice(0,12).map(i=>`<tr><td>${esc([i.name,i.brand,i.color,i.size].filter(Boolean).join(' · '))}</td><td>${esc(i.sku)}</td><td>${number(i.stock)}</td><td>${money(i.cost)}</td></tr>`).join('');markDialogClean($('#importDialog'));openDialog($('#importDialog'));}
$('#importCsv').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{let incoming;if(/\.xlsx?$/i.test(file.name)){if(typeof XLSX==='undefined')throw Error('Excel-Modul nicht geladen');const wb=XLSX.read(await file.arrayBuffer(),{type:'array'}),sheet=wb.Sheets[wb.SheetNames[0]],rows=XLSX.utils.sheet_to_json(sheet,{header:1,defval:'',raw:true});incoming=normalizeImportRows(rows);}else if(/\.xml$/i.test(file.name)||file.type.includes('xml'))incoming=parseInventoryXml(await file.text());else incoming=normalizeImportRows(parseCsv(await file.text()));showImportPreview(incoming,file.name);}catch(err){alert(`Import nicht möglich: ${err.message}`);}e.target.value='';};
$('#importForm').addEventListener('submit',e=>{
  e.preventDefault();const strategy=e.currentTarget.elements.strategy.value;if(!pendingImportRows.length)return;const previous=JSON.parse(JSON.stringify(state)),rows=pendingImportRows.slice();let added=0,updated=0,skipped=0;
  try{
    if(strategy!=='replace')assertUniqueInventoryCodes(state.items);
    if(strategy==='replace'){
      if(!confirm('Inventar vollständig ersetzen? Dabei werden auch bisherige Buchungen, Bestellungen und Momentaufnahmen gelöscht.'))return;
      state={items:rows.map(data=>({id:uid(),photo:'',visualSamples:[],...importItemData(data)})),transactions:[],orders:[],snapshots:[],categories:DEFAULT_CATEGORIES.map(c=>({...c})),brands:DEFAULT_BRANDS.slice(),materials:DEFAULT_MATERIALS.slice(),locations:[],barcodeGroups:[],settings:state.settings||{}};added=rows.length;
    }else{
      const baseItems=state.items.slice(),plan=rows.map(data=>({data,existing:findImportMatch(data,baseItems)})),targets=new Set();
      for(const entry of plan)if(entry.existing){if(targets.has(entry.existing.id))throw Error(`Mehrere Importzeilen zielen auf „${entry.existing.name}“. Bitte SKU und Barcode je Variante eindeutig zuordnen.`);targets.add(entry.existing.id);}
      plan.forEach(({data,existing})=>{if(existing&&strategy==='merge'){const clean=importItemData(data),patch={};for(const field of data._present||[])if(field in clean)patch[field]=clean[field];const stockBefore=existing.stock,costBefore=existing.cost;Object.assign(existing,patch);if(existing.stock!==stockBefore){const transaction={id:uid(),itemId:existing.id,itemName:existing.name,type:'adjustment',quantity:Math.abs(existing.stock-stockBefore),unitPrice:0,unitCost:costBefore,stockBefore,stockAfter:existing.stock,note:'Bestand per Datenimport aktualisiert',date:new Date().toISOString()};if(existing.cost!==costBefore){transaction.costBefore=costBefore;transaction.costAfter=existing.cost;}state.transactions.push(transaction);}updated++;}else if(!existing){state.items.push({id:uid(),photo:'',visualSamples:[],...importItemData(data)});added++;}else skipped++;});
    }
    assertUniqueInventoryCodes(state.items);
    state.items.forEach(item=>{ensureCategory(item.category);ensureBrand(item.brand);ensureMaterial(item.material);ensureLocation(item.location);});
    if(!persistState()){state=previous;return;}
    pendingImportRows=[];markDialogClean($('#importDialog'));renderAll();requestDialogClose($('#importDialog'),null,{skipDirty:true});toast(`${added} neu · ${updated} aktualisiert${skipped?` · ${skipped} übersprungen`:''}`);
  }catch(error){state=previous;alert(`Import abgebrochen: ${error.message}`);}
});
$('#resetData').onclick=()=>{if(confirm('Wirklich alle Artikel, Barcodegruppen, Lagerplätze, Bestellungen, Momentaufnahmen und Buchungen unwiderruflich löschen?')){state={items:[],transactions:[],orders:[],snapshots:[],categories:DEFAULT_CATEGORIES.map(c=>({...c})),brands:DEFAULT_BRANDS.slice(),materials:DEFAULT_MATERIALS.slice(),locations:[],barcodeGroups:[],settings:{categoryCatalogVersion:CATEGORY_CATALOG_VERSION}};save();toast('Alle Daten gelöscht');}};
